def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    last_opp = history[-1][1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

    if opp_c == n:
        if n >= 90:
            return 'D'
        if n > 30 and rng.random() < 0.12:
            return 'D'
        return 'C'

    if opp_c == 0:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    if n < 6:
        return 'D' if last_opp == 'D' else 'C'

    if n >= 95:
        return 'D' if opp_c * 2 >= n else 'C'

    recent = history[-8:]
    opp_recent_c = 0
    for a, b in recent:
        if b == 'C':
            opp_recent_c += 1

    recent3 = history[-3:]
    opp_recent3_d = 0
    for a, b in recent3:
        if b == 'D':
            opp_recent3_d += 1

    if opp_recent3_d == 3:
        if rng.random() < 0.10:
            return 'C'
        return 'D'

    if opp_recent_c <= 1:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    if opp_recent_c >= 7:
        if last_opp == 'D' and rng.random() < 0.65:
            return 'D'
        return 'C'

    coop_rate = opp_c / n
    my_rate = my_c / n

    if coop_rate > 0.7:
        if last_opp == 'D' and rng.random() < 0.6:
            return 'D'
        return 'C'

    if coop_rate < 0.25:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if coop_rate > 0.5 and my_rate > 0.5 and rng.random() < 0.35:
            return 'C'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    if my_rate > 0.8 and last_opp == 'C' and n % 9 == 8:
        return 'D'
    return 'C'
